mapper.select:
select user.id, user.name, user.gender, user.subscribe_number, user.username, user.experience, CASE WHEN user_subscribe.subscribed_id IS NOT NULL THEN TRUE ELSE FALSE END AS subscribeStatus from user left join user_subscribe on user.id = user_subscribe.subscribed_id and user_subscribe.user_id = #{UserId}
and user.name LIKE CONCAT('%', #{name}, '%')
and user.username = #{username}
and user.id = #{id}
user.is_deleted = 0
